import { RequestBodyBase } from "../RequestBodyBase";
import { Subscription } from "../../../lib/FluxSockets";

export class AddSubscriptionRequest extends RequestBodyBase {

    _addedSubscriptions: Subscription[];
    _isAddRequest: Boolean;
    _messageIdentifier: number

    public loadClientData(subs: Subscription | Subscription[], reqType: Boolean, mi): void {
        this._addedSubscriptions = Array.isArray(subs) ? subs : [subs];
        this._isAddRequest = reqType;
        this._messageIdentifier = mi;
    }
}
